import {REQUEST_COPY} from './shared/integrated-request-copy.js?v=5.17.0';
import {requestDateLimits} from './shared/integrated-request.js?v=5.17.0';
import {expansionCopy} from './shared/expansion-copy.js?v=5.8.0';
import {formatMoney} from './shared/locale.js?v=5.6.0';
import {esc} from './shared/core.js?v=5.6.0';
export function requestForm(demo,options={}){
 const l=demo.guestLang,c={...REQUEST_COPY[l],...options.copy},x=expansionCopy(l),d=demo.draft(),errors=demo.errors,limits=requestDateLimits(),menu=demo.menu();
 const id=key=>'integrated-input-'+key;
 const error=key=>errors[key]?`<small class="request-error" id="${id(key)}-error">${esc(c[errors[key]])}</small>`:'';
 const attrs=key=>`id="${id(key)}" name="${key}" ${errors[key]?`aria-invalid="true" aria-describedby="${id(key)}-error"`:''}`;
 const field=(key,label,type,extra='')=>`<div class="request-field"><label for="${id(key)}">${esc(label)}</label><input ${attrs(key)} type="${type}" value="${esc(d[key])}" ${extra} required>${error(key)}</div>`;
 const total=menu.reduce((sum,m)=>{const q=Number(d.quantities[m.id]);return sum+(Number.isInteger(q)&&q>=0&&q<=20?q*m.price:0);},0);
 return `<form class="integrated-request-form" novalidate aria-labelledby="integrated-request-title" lang="${l}"><h4 id="integrated-request-title">${esc(c.title)}</h4><p class="request-hint">${esc(c.hint)}</p>${Object.keys(errors).length?`<div class="request-errors" tabindex="-1" role="alert"><strong>${esc(c.errors)}</strong><ul>${Object.entries(errors).map(([key,code])=>`<li><a href="#${id(key==='menu'?'quantity-'+menu[0].id:key==='request'?(demo.scenario==='booking'?'date':'quantity-'+menu[0].id):key)}">${esc(c[code])}</a></li>`).join('')}</ul></div>`:''}${demo.scenario==='booking'?`${field('date',x.date,'date',`min="${limits.min}" max="${limits.max}"`)}${field('time',x.time+' · UTC+7','time','step="60"')}${field('partySize',x.party,'number','min="1" max="20" step="1" inputmode="numeric"')}`:`<fieldset class="request-menu"><legend>${esc(c.quantity)}</legend><p id="integrated-quantity-hint">${esc(c.zeroHint)}</p>${error('menu')}${menu.map(m=>`<div class="request-menu-row"><img src="jumo/${m.image}" alt="" width="36" height="36"><label for="${id('quantity-'+m.id)}"><b>${esc(m.name[l])}</b><small>${esc(formatMoney(m.price,l))}</small></label><input ${attrs('quantity-'+m.id)} type="number" min="0" max="20" step="1" inputmode="numeric" value="${esc(d.quantities[m.id])}" aria-label="${esc(m.name[l]+' · '+c.quantity)}" required>${error('quantity-'+m.id)}</div>`).join('')}</fieldset><div class="request-total"><span>${esc(c.total)}</span><output data-request-total>${esc(formatMoney(total,l))}</output></div>${demo.scenario==='delivery'?`<div class="request-field"><label for="${id('address')}">${esc(x.deliveryAddress)}</label><textarea ${attrs('address')} rows="3" minlength="5" maxlength="300" autocomplete="off" required>${esc(d.address)}</textarea>${error('address')}</div>${field('phone',x.contact,'tel','maxlength="30" autocomplete="off"')}`:''}`}<button type="submit" class="request-submit">${esc(c.submit)}</button>${options.footer||''}<p class="request-privacy">${esc(c.privacy)}</p></form>`;
}
